// ---- merge the global language packs (Spanish, Portuguese, French, Arabic, Indonesian)
for (const pack of PACKS) {
  for (const [k, v] of Object.entries(pack.numbers)) NUMBER_WORDS[normKey(k)] ??= v;
  for (const [k, v] of Object.entries(pack.units)) UNIT_WORDS[normKey(k)] ??= v;
  for (const [k, v] of Object.entries(pack.colors)) COLORS[normKey(k)] ??= v;
  for (const [k, v] of Object.entries(pack.sizes)) SIZES[normKey(k)] ??= v;
  for (const [k, v] of Object.entries(pack.deadlines)) DEADLINE_WORDS[normKey(k)] ??= v;
  for (const w of pack.stop) STOPWORDS.add(normKey(w));
  for (const w of pack.urgent) URGENT_WORDS.add(normKey(w));
}
MULTIPLIERS['mil'] = 1000;
